        db.execute("INSERT INTO external_group_audit_events(chat_id,actor_id,event_type,details,created_at) VALUES(?,?,?,?,?)",
                   (int(chat_id), int(actor_id or 0), str(event_type)[:80], str(details)[:1000], now()))
