def _render_member_welcome_image(member_name, member_number, member_id, username, date_text, time_text, title_text):
    """Embed live member fields into the exact approved navy/gold welcome-card image."""
    try:
        from PIL import Image, ImageDraw, ImageFont
        import base64 as _b64
        import io as _io

        image = Image.open(_io.BytesIO(_b64.b64decode(_WELCOME_TEMPLATE_B64))).convert("RGB")
        draw = ImageDraw.Draw(image)
        # Coordinates refer to the approved 1254x1254 template. Erase only the
        # example values; retain all decorations, table labels, rules and artwork.
        centers = [668, 713, 759, 805, 853, 901]
        values = [
            str(member_name or "عضو"),
            str(member_number),
            str(member_id),
            str(username or "لا يوجد"),
            str(date_text),
            str(time_text),
        ]
        # Reconstruct each row's soft horizontal background by interpolating
        # between clean pixels on either side of the example-value area.
        pixels = image.load()
        left_x, right_x = 320, 630
        for y in centers:
            for yy in range(y-20, y+21):
                left = pixels[left_x, yy]
                right = pixels[right_x, yy]
                for x in range(330, 626):
                    ratio = (x-left_x)/(right_x-left_x)
                    pixels[x, yy] = tuple(
                        int(left[ch]*(1-ratio) + right[ch]*ratio) for ch in range(3)
                    )

        # Arabic typeface; use a smaller size for long names/usernames to fit
        # the original value column cleanly.
        font_path = "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf"
        def fit_font(value, max_width=245, base_size=30, min_size=17):
            for size in range(base_size, min_size-1, -1):
                try:
                    f = ImageFont.truetype(font_path, size)
                except Exception:
                    f = ImageFont.load_default()
                box = draw.textbbox((0, 0), value, font=f, direction="rtl", language="ar")
                if box[2]-box[0] <= max_width:
                    return f
            return ImageFont.load_default()

        for idx, (y, value) in enumerate(zip(centers, values)):
            if idx == 5:  # keep the time's left-to-right order (e.g. 6:38 PM)
                direction, language = "ltr", "en"
            elif idx == 3 and value.startswith("@"):
                direction, language = "ltr", "en"
            else:
                direction, language = "rtl", "ar"
            # Keep the value centered where the template's sample value was.
            font = fit_font(value, base_size=29 if idx in (0, 3) else 30)
            draw.text((475, y), value, font=font, fill=(13, 25, 45),
                      anchor="mm", direction=direction, language=language)

        output = _io.BytesIO()
        image.save(output, format="JPEG", quality=94, optimize=True)
        output.seek(0)
        output.name = "welcome_member.jpg"
        return output
    except ImportError as exc:
        # Pillow is required to personalize the embedded welcome-card image.
        # Keep the exception explicit in Render logs so a missing dependency
        # can be distinguished from malformed template data or drawing errors.
        log.error(
            "WELCOME_IMAGE_RENDER_FAILED: required image dependency is unavailable (%s). "
            "Install Pillow from requirements.txt and redeploy.",
            exc,
            exc_info=True,
        )
        return None
    except Exception:
        log.exception("WELCOME_IMAGE_RENDER_FAILED")
        return None


async def _send_member_welcome_with_bot_photo(context, chat, member, approved=False):
    """Send one welcome with the approved bot logo and dynamic member details."""
    # Atomic DB reservation prevents chat_member and service-message updates
    # from sending duplicate welcomes for the same user in the same group.
    cur = db.execute(
        "INSERT OR IGNORE INTO welcome_sent_events(chat_id,user_id,event_type,sent_at) VALUES(?,?,?,?)",
        (chat.id, member.id, "approved" if approved else "direct", now()),
    )
    db.commit()
    if cur.rowcount == 0:
        log.info("WELCOME_DUPLICATE_SKIPPED chat_id=%s member_id=%s", chat.id, member.id)
        return False

    # Stable sequential membership number for this group.
    number_row = db.execute(
        "SELECT member_number FROM group_member_numbers WHERE chat_id=? AND user_id=?",
        (chat.id, member.id),
    ).fetchone()
    if number_row:
        member_number = number_row[0]
    else:
        max_row = db.execute(
            "SELECT COALESCE(MAX(member_number),0) FROM group_member_numbers WHERE chat_id=?",
            (chat.id,),
        ).fetchone()
        member_number = int(max_row[0] or 0) + 1
        db.execute(
            "INSERT OR IGNORE INTO group_member_numbers(chat_id,user_id,member_number) VALUES(?,?,?)",
            (chat.id, member.id, member_number),
        )
        db.commit()
        number_row = db.execute(
            "SELECT member_number FROM group_member_numbers WHERE chat_id=? AND user_id=?",
            (chat.id, member.id),
        ).fetchone()
        member_number = number_row[0] if number_row else member_number

    moment = _riyadh_now()
    raw_name = (getattr(member, "full_name", None) or getattr(member, "first_name", None) or "عضو").strip()
    # Avoid a punctuation-only display name (for example "."), which appeared blank.
    if not any(ch.isalnum() for ch in raw_name):
        raw_name = (getattr(member, "first_name", None) or "عضو").strip()
        if not any(ch.isalnum() for ch in raw_name):
            raw_name = "عضو"
    display_name = html.escape(raw_name)
    username_value = getattr(member, "username", None)
    username = "@" + html.escape(username_value) if username_value else "لا يوجد"
    title = "تـم اعـتـمـاد قـبـول طـلـب انـضـمـامـك" if approved else "عـضـو جـديـد"

    text = (
        f"ᯓ˹ 𝐖𝐄𝐋𝐂𝐎𝐌𝐄 ♛ ♛ {title} ♛ ˼\n"
        "°•━━━━━━━━━━ ✦ ♛ ✦ ━━━━━━━━━•°\n\n"
        f"👑 نـوّرت قـروبـاتـنـا وشـرّفـتـنا بـ 『{display_name}』 🤍\n\n"
        f"°︙ اسـم الـعـضـو ⇚ 『{display_name}』\n"
        f"°︙ رقـم الـعـضـويـة ⇚ 『{member_number}』\n"
        f"°︙ حـسـاب ID ⇚ 『{member.id}』\n"
        f"°︙ الـيـوزر ⇚ 『{username}』\n"
        f"°︙ تـاريـخ الـقـبـول ⇚ 『{moment.strftime('%d-%m-%Y')}』\n"
        f"°︙ سـاعـة الـقـبـول ⇚ 『{moment.strftime('%I:%M %p').lstrip('0')}』\n\n"
        "✦ نـرحّـب بـك فـي قـروبـاتـنـا، حـيـث يـجـتـمـع الـعـطـاء والـتـمـيّـز، ونـسـعـد بـانـضـمـامـك إلـيـنـا.\n"
        "فـوجـودك إضـافـة جـمـيـلـة، ونـتـمـنـى لـك رحـلـة مـلـيـئـة بـالـفـائـدة والإنـجـاز 🌷\n\n"
        "°•━━━━━━━━━━ ✦ ♛ ✦ ━━━━━━━━━•°"
    )

    try:
        welcome_image = _render_member_welcome_image(
            member_name=raw_name,
            member_number=member_number,
            member_id=member.id,
            username=username_value or "لا يوجد",
            date_text=moment.strftime("%d-%m-%Y"),
            time_text=moment.strftime("%I:%M %p").lstrip("0"),
            title_text=title,
        )
        if welcome_image is None:
            raise RuntimeError("Dynamic welcome image renderer returned no image")
        await context.bot.send_photo(chat_id=chat.id, photo=welcome_image)
        log.info(
            "WELCOME_SENT chat_id=%s member_id=%s approved=%s photo_attempted=1 dynamic_data_in_image=1",
            chat.id, member.id, approved,
        )
        return True
    except Exception:
        log.exception(
            "WELCOME_DYNAMIC_IMAGE_SEND_FAILED chat_id=%s member_id=%s; sending text fallback",
            chat.id, member.id,
        )
        try:
            await context.bot.send_message(chat_id=chat.id, text=text[:4000], parse_mode="HTML")
            return True
        except Exception:
            log.exception("WELCOME_TEXT_FALLBACK_FAILED chat_id=%s member_id=%s", chat.id, member.id)
            db.execute(
                "DELETE FROM welcome_sent_events WHERE chat_id=? AND user_id=?",
                (chat.id, member.id),
            )
            db.commit()
            return False


async def new_members(update, context):
    """Record new members and send welcome independently of owner notifications.

    A failure to DM the owner must never prevent the group welcome from being sent.
    If no custom welcome is configured, send a safe default so the welcome feature
    does not appear to do nothing after selecting a group in the panel.
    """
    msg = update.effective_message
    chat = update.effective_chat
    if not msg or not chat or not msg.new_chat_members:
        return

    try:
        register_group(chat)
        # Only suppress welcomes when this chat is explicitly tracked as an external
        # group and has been disabled. Ordinary registered groups may not have an
        # external_group_control row, so a missing row must not silently disable welcomes.
        _welcome_group_control = external_group_info(chat.id)
        if _welcome_group_control and _welcome_group_control[0] and not _welcome_group_control[1]:
            log.info("WELCOME_SKIPPED_EXTERNAL_GROUP_DISABLED chat_id=%s", chat.id)
            return
        settings = get_settings(chat.id)
    except Exception:
        log.exception("WELCOME_SETUP_FAILED chat_id=%s", getattr(chat, "id", None))
        settings = {"entry": 0, "verify_new_members": 0}

    try:
        welcome_row = db.execute(
            "SELECT message FROM welcome_messages WHERE chat_id=?", (chat.id,)
        ).fetchone()
        configured_welcome = welcome_row[0].strip() if welcome_row and welcome_row[0] else ""
        if not external_group_cap_enabled(chat.id, "welcome"):
            configured_welcome = ""
    except Exception:
        log.exception("WELCOME_CONFIG_READ_FAILED chat_id=%s", chat.id)
        configured_welcome = ""

    group_title = chat.title or "القروب"
    _adding_actor = getattr(msg, "from_user", None)
    log.info(
        "NEW_MEMBER_SERVICE chat_id=%s actor_id=%s approval_enabled=%s",
        chat.id, int(getattr(_adding_actor, "id", 0) or 0),
        int(group_feature_enabled(chat.id, "join_approval_enabled")),
    )
    for member in msg.new_chat_members:
        if member.is_bot:
            continue
        _owner_deputy_direct_add = is_authorized_manual_add(chat.id, member, _adding_actor)
        if group_feature_enabled(chat.id, "join_approval_enabled") and not _owner_deputy_direct_add:
            approval_row = db.execute("SELECT status FROM join_request_events WHERE chat_id=? AND user_id=?", (chat.id, member.id)).fetchone()
            if not approval_row or approval_row[0] not in ("approved", "joined"):
                # This handler only controls welcome/verification side effects. The
                # authoritative membership enforcement is handled once in
                # chat_member_handler, avoiding a second actor check based on Message.from_user.
                log.info("NEW_MEMBER_APPROVAL_WELCOME_SKIPPED chat_id=%s member_id=%s actor_id=%s", chat.id, member.id, int(getattr(_adding_actor, "id", 0) or 0))
                continue
        if global_ban_applies(member.id, chat.id) and not _owner_deputy_direct_add:
            # Enforcement is centralized in chat_member_handler, where Telegram's
            # ChatMemberUpdated.from_user is the authoritative actor. Do not issue a
            # second ban from the service-message handler: Telegram may report a
            # different/missing from_user on the service Message, which previously
            # caused authorized owner/deputy/delegate additions to be undone here.
            log.info(
                "NEW_MEMBER_GLOBAL_BAN_DEFERRED chat_id=%s member_id=%s actor_id=%s reason=centralized_chat_member_enforcement",
                chat.id, member.id, int(getattr(_adding_actor, "id", 0) or 0),
            )
            continue

        display_name = member.full_name or "عضو"
        try:
            db.execute(
                "INSERT INTO member_activity(chat_id,user_id,display_name,message_count,stars,custom_title,username) "
                "VALUES(?,?,?,0,0,'',?) ON CONFLICT(chat_id,user_id) DO UPDATE SET "
                "display_name=excluded.display_name, username=excluded.username",
                (chat.id, member.id, display_name, member.username or "")
            )
            db.commit()
        except Exception:
            log.exception("MEMBER_ACTIVITY_SAVE_FAILED chat_id=%s member_id=%s", chat.id, member.id)

        # Keep the existing per-group welcome toggle; use the bot profile photo and separate templates.
        if external_group_cap_enabled(chat.id, "welcome") and not _owner_deputy_direct_add:
            approval_row = db.execute(
                "SELECT status FROM join_request_events WHERE chat_id=? AND user_id=?", (chat.id, member.id)
            ).fetchone()
            approved = bool(approval_row and approval_row[0] in ("approved", "joined"))
            await _send_member_welcome_with_bot_photo(context, chat, member, approved=approved)
        elif _owner_deputy_direct_add:
            log.info("PUBLIC_WELCOME_SUPPRESSED_MANUAL_ADD_SERVICE chat_id=%s member_id=%s actor_id=%s", chat.id, member.id, int(getattr(_adding_actor, "id", 0) or 0))
        else:
            log.info("WELCOME_DISABLED chat_id=%s member_id=%s", chat.id, member.id)

        try:
            await notify_owners(
                context,
                f"👋 دخول عضو جديد\nالمجموعة: {group_title}\nالعضو: {display_name}\nالمعرّف: {member.id}",
                "membership"
            )
        except Exception:
            log.exception("NEW_MEMBER_OWNER_ALERT_FAILED chat_id=%s member_id=%s", chat.id, member.id)

        if settings.get("verify_new_members", 0):
            try:
                await context.bot.restrict_chat_member(
                    chat_id=chat.id, user_id=member.id,
                    permissions=ChatPermissions(
                        can_send_messages=False, can_send_audios=False,
                        can_send_documents=False, can_send_photos=False,
                        can_send_videos=False, can_send_video_notes=False,
                        can_send_voice_notes=False, can_send_polls=False,
                        can_send_other_messages=False, can_add_web_page_previews=False
                    )
                )
                db.execute(
                    "INSERT OR REPLACE INTO pending_verifications(chat_id,user_id,created_at) VALUES(?,?,?)",
                    (chat.id, member.id, now())
                )
                db.commit()
                await context.bot.send_message(
                    chat_id=chat.id,
                    text=f"👤 أهلًا {display_name}! أكمل التحقق خلال دقيقتين للمشاركة في القروب.",
                    reply_markup=InlineKeyboardMarkup([[
                        InlineKeyboardButton("✅ أنا إنسان — تحقق", callback_data=f"verify_member:{chat.id}:{member.id}")
                    ]])
                )
                context.application.create_task(verification_timeout(context.bot, chat.id, member.id))
            except Exception as exc:
                try:
                    db.execute("DELETE FROM pending_verifications WHERE chat_id=? AND user_id=?", (chat.id, member.id))
                    db.commit()
                except Exception:
                    log.exception("VERIFY_STATE_CLEANUP_FAILED chat_id=%s member_id=%s", chat.id, member.id)
                log.warning("تعذر بدء التحقق للعضو %s في %s: %s", member.id, chat.id, exc)
                try:
                    await notify_owners(
                        context,
                        f"⚠️ تعذر بدء التحقق من عضو جديد\nالقروب: {group_title} ({chat.id})\n"
                        f"العضو: {display_name} (ID: {member.id})\nتحقق من صلاحيات البوت كمشرف.",
                        "security"
                    )
                except Exception:
                    log.exception("VERIFY_FAILURE_OWNER_ALERT_FAILED chat_id=%s", chat.id)

    if settings.get("entry", 0):
        try:
            await msg.delete()
        except Exception as exc:
            log.info("ENTRY_SERVICE_DELETE_FAILED chat_id=%s error=%r", chat.id, exc)

async def service_add_handler(update, context):
    msg = update.message
    chat = update.effective_chat
    if not msg or not chat or not msg.new_chat_members:
        return
    s = get_settings(chat.id)
    # Hide Telegram's native "X added Y" service notice only when the actor is
    # positively identified as the primary owner, deputy, or delegated owner.
    # Self-joins and invite-link / approved-request entries retain normal notices.
    actor = getattr(msg, "from_user", None)
    human_members = [member for member in msg.new_chat_members if not getattr(member, "is_bot", False)]
    authorized_manual_batch = bool(human_members) and all(
        is_authorized_manual_add(chat.id, member, actor) for member in human_members
    )
    if s.get("add_lock") or authorized_manual_batch:
        try:
            await msg.delete()
            if authorized_manual_batch:
                log.info("PUBLIC_NATIVE_ADD_SERVICE_SUPPRESSED chat_id=%s actor_id=%s members=%s",
                         chat.id, getattr(actor, "id", 0), len(human_members))
        except Exception as exc:
            log.info("ADD_SERVICE_DELETE_FAILED chat_id=%s authorized_manual=%s error=%r",
                     chat.id, int(authorized_manual_batch), exc)

async def broadcast_draft_message(update, context):
    msg = update.effective_message
    user = update.effective_user
    chat = update.effective_chat
    if not msg or not user or not chat or chat.type != ChatType.PRIVATE:
        return
    remember_delegated_user(user)
    if context.user_data.get("awaiting_staff_permissions_id"):
        # Do not consume a mistyped command as a numeric user ID. Clear this
        # pending state and tell the owner how to run the command correctly.
        raw_probe = (msg.text or "").strip().casefold().lstrip("/").rstrip("/").strip()
        if raw_probe == "aigroups" or raw_probe.startswith("aigroups ") or raw_probe == "ai groups":
            context.user_data.pop("awaiting_staff_permissions_id", None)
            await msg.reply_text("ℹ️ ألغيت انتظار رقم المستخدم حتى لا يتعارض مع الأمر. لإدارة الذكاء الاصطناعي أرسل الأمر كما هو مع الشرطة المائلة في البداية:\n/aigroups\nثم اختر أحد الأمثلة:\n/aigroups list\n/aigroups all on\n/aigroups all off")
            return
        if not (is_owner(user.id) or is_delegated_owner(user.id)):
            context.user_data.pop("awaiting_staff_permissions_id", None)
            await msg.reply_text("⛔ إدارة صلاحيات الطاقم للمالك أو المالك المفوّض فقط.")
            return
        raw_id = (msg.text or "").strip()
        # Avoid trapping the owner in a stale numeric-ID prompt: command-like input cancels the prompt.
        normalized_command = raw_id.casefold().lstrip("/").rstrip("/").strip()
        if raw_id.startswith("/") or normalized_command.startswith(("aigroups", "panel", "help", "start", "cancel", "ai ")):
            context.user_data.pop("awaiting_staff_permissions_id", None)
            await msg.reply_text("ℹ️ ألغيت انتظار رقم المستخدم. أعد إرسال الأمر المطلوب الآن، مثل /aigroups list أو /aigroups all off.")
            return
        if not raw_id.isdigit() or int(raw_id) <= 0:
            context.user_data.pop("awaiting_staff_permissions_id", None)
            await msg.reply_text("❌ أُلغيت عملية إدخال رقم المستخدم لأن المدخل غير رقمي. أعد الأمر المطلوب من جديد، أو استخدم /cancel لإلغاء العمليات.")
            return
        target_uid = int(raw_id)
        if target_uid == OWNER_ID or is_delegated_owner(target_uid):
            await msg.reply_text("⛔ لا يمكن تعديل صلاحيات المالك الأساسي أو المالك المفوّض من هذه اللوحة.")
            context.user_data.pop("awaiting_staff_permissions_id", None)
            return
        context.user_data.pop("awaiting_staff_permissions_id", None)
        await msg.reply_text(
            f"👥 إدارة المشرفين والمدراء والصلاحيات\n\nالمستخدم: {user_display_name(target_uid)}\nالمعرّف: {target_uid}\n\nاختر الرتبة أو الصلاحيات المطلوبة. الصلاحيات ذات علامة ✅ مفعّلة لجميع القروبات المسجلة.",
            reply_markup=staff_permissions_markup(target_uid)
        )
        return
    if context.user_data.get("awaiting_delegated_owner_id"):
        if not can_manage_delegates(user.id):
            context.user_data.pop("awaiting_delegated_owner_id", None)
            await msg.reply_text("⛔ تحتاج صلاحية إدارة المفوضين من المالك الأساسي.")
            return
        raw_id = (msg.text or "").strip()
        if not raw_id.isdigit():
            await msg.reply_text("أرسل رقم المستخدم فقط، أو اضغط إلغاء من لوحة التحكم.")
            return
        target_uid = int(raw_id)
        if target_uid <= 0 or target_uid == OWNER_ID:
            await msg.reply_text("❌ رقم غير صالح أو هذا الحساب هو المالك الأساسي بالفعل.")
            return
        if db.execute("SELECT 1 FROM deputy_owners WHERE user_id=?", (target_uid,)).fetchone():
            await msg.reply_text("هذا المستخدم مسجل بالفعل كنائب للمالك؛ أزل رتبته الحالية أولًا قبل تعيينه مالكًا مفوّضًا.")
            return
        try:
            target_chat = await context.bot.get_chat(target_uid)
            if getattr(target_chat, "is_bot", False):
                await msg.reply_text("❌ لا يمكن تعيين حساب بوت كمالك مفوّض.")
                return
            display_name = getattr(target_chat, "full_name", "") or getattr(target_chat, "first_name", "") or ""
            username = getattr(target_chat, "username", "") or ""
        except Exception:
            # Telegram may not reveal a user until they have started the bot; ID can still be recorded.
            display_name, username = "", ""
        db.execute("""INSERT INTO delegated_owners(user_id,added_by,added_at,display_name,username)
                      VALUES(?,?,?,?,?) ON CONFLICT(user_id) DO UPDATE SET added_by=excluded.added_by,
                      added_at=excluded.added_at,
                      display_name=CASE WHEN excluded.display_name!='' THEN excluded.display_name ELSE delegated_owners.display_name END,
                      username=CASE WHEN excluded.username!='' THEN excluded.username ELSE delegated_owners.username END""",
                   (target_uid, user.id, now(), display_name, username))
        db.commit()
        context.user_data.pop("awaiting_delegated_owner_id", None)
        await msg.reply_text(
            f"✅ تم تسجيل المعرّف {target_uid} كمالك مفوّض.\n"
            "✅ لديه صلاحيات الإدارة التشغيلية للقروبات والأعضاء.\n"
            "🔐 امتلاك البوت وإعداداته الرئيسية وتغيير المالك الأساسي تبقى حصرًا للمالك الأساسي.\n"
            "➕ لا يستطيع إدارة المفوضين إلا إذا منحه المالك الأساسي هذه الصلاحية صراحةً.",
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("👑 إدارة المالك المفوّض", callback_data="delegated_owner")]])
        )
        return
    # Unified campaign composer: accepts text, photos, videos and documents.
    if context.user_data.get("awaiting_campaign_content") and (is_owner(user.id) or is_delegated_owner(user.id) or can_use_capability(user.id, "publish")):
        targets = context.user_data.get("campaign_selected_targets", [])
        if not targets:
            context.user_data.pop("awaiting_campaign_content", None)
            await msg.reply_text("⛔ لا توجد جهات نشر محددة. ابدأ حملة جديدة من اللوحة.")
            return
        context.user_data["campaign_draft"] = {"chat_id": chat.id, "message_id": msg.message_id}
        context.user_data.pop("awaiting_campaign_content", None)
        groups_count = sum(1 for t in targets if t.get("kind") == "group")
        channels_count = sum(1 for t in targets if t.get("kind") == "channel")
        await msg.reply_text(
            "👀 معاينة الحملة جاهزة\n"
            f"القروبات: {groups_count} | القنوات: {channels_count}\n"
            f"إجمالي الجهات: {len(targets)}\n\nاختر طريقة التنفيذ:",
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton("🚀 نشر الآن", callback_data="campaign_publish_now")],
                [InlineKeyboardButton("🗓️ جدولة الحملة", callback_data="campaign_schedule")],
                [InlineKeyboardButton("❌ إلغاء", callback_data="campaign_cancel")],
            ])
        )
        return
    if context.user_data.get("awaiting_campaign_reschedule") and (is_owner(user.id) or is_delegated_owner(user.id) or can_use_capability(user.id, "publish")):
        raw = (msg.text or "").strip()
        campaign_id = int(context.user_data.get("awaiting_campaign_reschedule") or 0)
        try:
            scheduled = datetime.strptime(raw, "%Y-%m-%d %H:%M").replace(tzinfo=ZoneInfo("Asia/Riyadh"))
            if scheduled <= datetime.now(ZoneInfo("Asia/Riyadh")):
                raise ValueError("الموعد يجب أن يكون في المستقبل")
        except Exception:
            await msg.reply_text("صيغة الموعد غير صحيحة أو الموعد مضى. أرسل YYYY-MM-DD HH:MM بتوقيت السعودية.")
            return
        row = db.execute("SELECT creator_id,status FROM publish_campaigns WHERE id=?", (campaign_id,)).fetchone()
        if not row or row[1] != "scheduled" or (not is_owner(user.id) and int(row[0]) != user.id):
            context.user_data.pop("awaiting_campaign_reschedule", None)
            await msg.reply_text("لا يمكن تعديل هذه الحملة؛ ربما نُشرت أو لا تملك صلاحية إدارتها.")
            return
        db.execute("UPDATE publish_campaigns SET scheduled_at=? WHERE id=? AND status='scheduled'",
                   (scheduled.strftime("%Y-%m-%d %H:%M"), campaign_id))
        db.commit()
        context.user_data.pop("awaiting_campaign_reschedule", None)
        await msg.reply_text(f"✅ تم تعديل موعد الحملة #{campaign_id} إلى {scheduled.strftime('%Y-%m-%d %H:%M')} بتوقيت السعودية.")
        return
    if context.user_data.get("awaiting_campaign_schedule") and (is_owner(user.id) or is_delegated_owner(user.id) or can_use_capability(user.id, "publish")):
        raw = (msg.text or "").strip()
        try:
            scheduled = datetime.strptime(raw, "%Y-%m-%d %H:%M").replace(tzinfo=ZoneInfo("Asia/Riyadh"))
            if scheduled <= datetime.now(ZoneInfo("Asia/Riyadh")):
                raise ValueError("الموعد يجب أن يكون في المستقبل")
        except Exception:
            await msg.reply_text("صيغة الموعد غير صحيحة أو الموعد مضى. أرسل التاريخ والوقت هكذا:\n2026-11-20 21:30\nبتوقيت السعودية، أو أرسل /cancel للإلغاء.")
            return
        draft = context.user_data.get("campaign_draft")
        targets = context.user_data.get("campaign_selected_targets", [])
        if not draft or not targets:
            context.user_data.pop("awaiting_campaign_schedule", None)
            await msg.reply_text("انتهت صلاحية مسودة الحملة. ابدأ من جديد.")
            return
        cur = db.execute("INSERT INTO publish_campaigns(creator_id,source_chat_id,source_message_id,targets_json,scheduled_at,status,created_at) VALUES(?,?,?,?,?,'scheduled',?)",
                         (user.id, draft["chat_id"], draft["message_id"], json.dumps(targets, ensure_ascii=False), scheduled.strftime("%Y-%m-%d %H:%M"), now()))
        db.commit()
        campaign_id = cur.lastrowid
        for key in ("awaiting_campaign_schedule", "campaign_draft", "campaign_selected_targets"):
            context.user_data.pop(key, None)
        await msg.reply_text(f"✅ تمت جدولة الحملة رقم #{campaign_id}\nالموعد: {scheduled.strftime('%Y-%m-%d %H:%M')} بتوقيت السعودية.")
        return
    # Handle an active broadcast draft BEFORE pending admin actions. Otherwise a
    # stale awaiting_admin_action flag can intercept the ad and demand a numeric ID.
    if context.user_data.get("awaiting_broadcast") and (is_owner(user.id) or is_delegated_owner(user.id)):
        context.user_data.pop("awaiting_admin_action", None)
        context.user_data["broadcast_draft"] = {"chat_id": chat.id, "message_id": msg.message_id}
        selected = context.user_data.get("broadcast_selected_groups", [])
        await msg.reply_text(
            "👀 معاينة الإعلان جاهزة. سيتم إرساله فقط إلى القروبات المحددة والمصرح لك بها.\n"
            f"عدد القروبات المستهدفة: {len(selected)}\nهل تريد المتابعة؟",
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton("✅ تأكيد النشر للقروبات المحددة", callback_data="broadcast_confirm")],
                [InlineKeyboardButton("❌ إلغاء", callback_data="broadcast_cancel")]
            ])
        )
        context.user_data["awaiting_broadcast"] = False
        return
    pending_action = context.user_data.get("awaiting_admin_action")
    if pending_action:
        raw = (msg.text or "").strip()
        if not raw.isdigit():
            await msg.reply_text("أرسل رقمًا صحيحًا فقط، أو افتح لوحة /panel للإلغاء.")
            return
        action = pending_action.get("action")
        target_id = int(raw)
        chat_id = int(pending_action.get("chat_id"))
        permission_for_action = {"ban":"ban", "unban":"unban", "kick":"kick", "mute":"mute", "unmute":"unmute", "delete":"delete", "pin":"pin"}.get(action)
        if not await can_access_group(context.bot, user.id, chat_id) or not permission_for_action or not has_group_permission(chat_id, user.id, permission_for_action):
            context.user_data.pop("awaiting_admin_action", None)
            await msg.reply_text("⛔ لا تملك الصلاحية المطلوبة لهذا الإجراء في هذا القروب.")
            return
        try:
            if action == "ban":
                await context.bot.ban_chat_member(chat_id, target_id)
            elif action == "unban":
                await context.bot.unban_chat_member(chat_id, target_id, only_if_banned=True)
            elif action == "kick":
                await context.bot.ban_chat_member(chat_id, target_id)
                await context.bot.unban_chat_member(chat_id, target_id, only_if_banned=True)
            elif action == "mute":
                await context.bot.restrict_chat_member(chat_id, target_id, permissions=ChatPermissions(can_send_messages=False))
                db.execute("INSERT OR REPLACE INTO group_mutes(chat_id,user_id,muted_by,muted_at) VALUES(?,?,?,?)", (chat_id, target_id, user.id, now())); db.commit()
            elif action == "unmute":
                await context.bot.restrict_chat_member(chat_id, target_id, permissions=ChatPermissions(can_send_messages=True, can_send_audios=True, can_send_documents=True, can_send_photos=True, can_send_videos=True, can_send_video_notes=True, can_send_voice_notes=True, can_send_polls=True, can_send_other_messages=True, can_add_web_page_previews=True))
                db.execute("DELETE FROM group_mutes WHERE chat_id=? AND user_id=?", (chat_id, target_id)); db.commit()
            elif action == "delete":
                await context.bot.delete_message(chat_id, target_id)
            elif action == "pin":
                await context.bot.pin_chat_message(chat_id, target_id)
            labels = {"ban":"حظر العضو", "unban":"فك حظر العضو", "kick":"طرد العضو", "mute":"كتم العضو", "unmute":"إلغاء كتم العضو", "delete":"حذف الرسالة", "pin":"تثبيت الرسالة"}
            log_action(chat_id, user.id, action, str(target_id))
            await msg.reply_text(f"✅ تم تنفيذ: {labels.get(action, action)}\nالقروب: {chat_id}\nالرقم: {target_id}")
        except Exception as exc:
            log.warning("Private group action %s failed in %s for %s: %s", action, chat_id, target_id, exc)
            await msg.reply_text("❌ تعذر تنفيذ الإجراء. تأكد من صحة الرقم، وأن البوت مشرف في القروب ولديه الصلاحية المطلوبة، وأن العضو/الرسالة قابلان لهذا الإجراء.")
        finally:
            context.user_data.pop("awaiting_admin_action", None)
        return
    welcome_chat_id = context.user_data.get("awaiting_welcome_chat")
    if welcome_chat_id and (is_general_manager(user.id) or is_protection_manager(user.id) or is_delegated_owner(user.id)) and await can_access_group(context.bot, user.id, welcome_chat_id):
        body = msg.text or msg.caption
        if not body:
            await msg.reply_text("أرسل نص ترحيب أو تعليقًا نصيًا.")
            return
        db.execute("INSERT OR REPLACE INTO welcome_messages(chat_id,message) VALUES(?,?)", (welcome_chat_id, body[:1000]))
        db.commit()
        log_action(welcome_chat_id, user.id, "welcome_set", "تم تحديث رسالة الترحيب")
        context.user_data.pop("awaiting_welcome_chat", None)
        await msg.reply_text("✅ تم حفظ رسالة الترحيب. ستُرسل عند دخول أعضاء جدد إذا كان البوت قادرًا على إرسال الرسائل في القروب.")
        return

async def _render_trigger_latest_deploy():
    """Trigger a Render deploy of the latest commit from the service's configured repository."""
    if not RENDER_API_KEY or not RENDER_SERVICE_ID:
        raise RuntimeError("يلزم ضبط RENDER_API_KEY وRENDER_SERVICE_ID في متغيرات البيئة.")
    import urllib.request
    import urllib.error

    url = f"https://api.render.com/v1/services/{RENDER_SERVICE_ID}/deploys"
    req = urllib.request.Request(
        url,
        data=b"{}",
        headers={
            "Authorization": f"Bearer {RENDER_API_KEY}",
            "Accept": "application/json",
            "Content-Type": "application/json",
        },
        method="POST",
    )

    def _request():
        try:
            with urllib.request.urlopen(req, timeout=20) as response:
                body = response.read().decode("utf-8", errors="replace")
                return response.status, body
        except urllib.error.HTTPError as exc:
            detail = exc.read().decode("utf-8", errors="replace")[:500]
            raise RuntimeError(f"رفض Render الطلب (HTTP {exc.code}): {detail}") from exc
        except Exception as exc:
            raise RuntimeError(f"تعذر الاتصال بخدمة Render: {exc}") from exc

    status, body = await asyncio.to_thread(_request)
    try:
        payload = json.loads(body) if body else {}
    except Exception:
        payload = {}
    deploy_id = payload.get("id") or payload.get("deploy", {}).get("id") or ""
    return status, deploy_id


