async def group_analysis_report_worker(app):
    """Daily owner/delegated-owner report at 20:30 Riyadh time."""
    while True:
        try:
            now_local = _riyadh_now()
            target = now_local.replace(hour=20, minute=30, second=0, microsecond=0)
            if target <= now_local:
                target += __import__("datetime").timedelta(days=1)
            await asyncio.sleep(max(30, (target - now_local).total_seconds()))
            recipients = {int(OWNER_ID)} if OWNER_ID else set()
            recipients.update(row[0] for row in db.execute("SELECT user_id FROM staff_capabilities WHERE capability='ai'").fetchall())
            for recipient in sorted(recipients):
                await send_group_analysis_report(app.bot, recipient)
            await asyncio.sleep(60)
        except asyncio.CancelledError:
            raise
        except Exception:
            log.exception("خطأ في عامل تقارير تحليل القروبات")
            await asyncio.sleep(60)




async def weekly_security_review_worker(app):
    """Weekly review of aggregate security/configuration signals; AI receives metrics only."""
    while True:
        try:
            now_local = _riyadh_now()
            target = now_local.replace(hour=9, minute=0, second=0, microsecond=0)
            days_ahead = (0 - now_local.weekday()) % 7
            if days_ahead == 0 and target <= now_local:
                days_ahead = 7
            target += __import__("datetime").timedelta(days=days_ahead)
            await asyncio.sleep(max(30, (target - now_local).total_seconds()))
            week_key = _week_start()
            if db.execute("SELECT 1 FROM security_review_runs WHERE week_start=?", (week_key,)).fetchone():
                await asyncio.sleep(3600)
                continue
            total_groups = int(db.execute("SELECT COUNT(*) FROM watched_groups").fetchone()[0] or 0)
            external_groups = int(db.execute("SELECT COUNT(*) FROM external_group_control WHERE is_external=1").fetchone()[0] or 0)
            disabled_groups = int(db.execute("SELECT COUNT(*) FROM external_group_control WHERE is_external=1 AND enabled=0").fetchone()[0] or 0)
            ai_enabled_groups = db.execute("SELECT chat_id,title FROM external_group_control WHERE is_external=1 AND ai_enabled=1 ORDER BY title").fetchall()
            links_open = db.execute("""SELECT w.chat_id,w.title FROM watched_groups w JOIN settings s ON s.chat_id=w.chat_id
                WHERE COALESCE(s.links,1)=0 ORDER BY w.title LIMIT 30""").fetchall()
            violation_count = int(db.execute("SELECT COUNT(*) FROM member_violations WHERE warning_count>0").fetchone()[0] or 0)
            active_bans = int(db.execute("SELECT COUNT(*) FROM global_bans WHERE active=1").fetchone()[0] or 0)
            new_tickets = int(db.execute("SELECT COUNT(*) FROM external_support_tickets WHERE status='new'").fetchone()[0] or 0)
            latest_actions = db.execute("SELECT action,COUNT(*) FROM logs WHERE created_at>=? GROUP BY action ORDER BY COUNT(*) DESC LIMIT 8",
                                        ((now_local - __import__("datetime").timedelta(days=7)).isoformat(),)).fetchall()
            source_syntax_ok = False
            try:
                with open(__file__, "r", encoding="utf-8") as _source_file:
                    compile(_source_file.read(), __file__, "exec")
                source_syntax_ok = True
            except Exception as source_exc:
                log.error("Weekly source syntax/integrity check failed: %s", source_exc)
            metrics = {
                "source_syntax_ok": source_syntax_ok,
                "bot_token_configured": bool(TOKEN),
                "owner_id_configured": bool(OWNER_ID),
                "groups_total": total_groups, "external_groups": external_groups, "disabled_external_groups": disabled_groups,
                "external_ai_enabled_groups": [{"chat_id":r[0],"title":r[1]} for r in ai_enabled_groups],
                "groups_with_links_open": [{"chat_id":r[0],"title":r[1]} for r in links_open],
                "members_with_violations": violation_count, "active_global_bans": active_bans,
                "unanswered_support_tickets": new_tickets, "top_actions_last_7_days": latest_actions
            }
            report = (
                "🛡️ المراجعة الأمنية الأسبوعية للبوت\n\n"
                f"فحص صياغة الكود: {'ناجح' if source_syntax_ok else 'فشل — يتطلب مراجعة عاجلة'}\n"
                f"إعداد رمز البوت: {'موجود' if TOKEN else 'غير موجود'} | إعداد المالك: {'موجود' if OWNER_ID else 'غير موجود'}\n"
                f"القروبات المسجلة: {total_groups}\nالقروبات الخارجية: {external_groups}\n"
                f"القروبات الخارجية المتوقفة: {disabled_groups}\nالقروبات الخارجية المفعّل لها الذكاء يدويًا: {len(ai_enabled_groups)}\n"
                f"القروبات المفتوحة فيها الروابط: {len(links_open)}\nالأعضاء ذوو المخالفات المسجلة: {violation_count}\n"
                f"حالات الحظر الجماعي النشطة: {active_bans}\nطلبات الدعم الجديدة: {new_tickets}\n"
                "مؤشرات آخر أسبوع: " + (", ".join(f"{a} ({n})" for a,n in latest_actions) or "لا توجد إجراءات مسجلة") + "\n\n"
                "التوصيات: راجع القروبات التي الروابط فيها مفتوحة، وطلبات الدعم غير المجابة، وأي صلاحيات إضافية مفعّلة. "
                "لا يجري تعديل الكود أو نشر تحديث برمجي تلقائيًا دون اختبارات وموافقة؛ هذا يمنع تحديثًا غير موثوق من تعطيل الحماية."
            )
            if OPENAI_API_KEY:
                try:
                    ai_summary = await openai_assistant_response(
                        "راجع مؤشرات الأمان المجمعة التالية فقط، ولا تفترض وجود اختراق دون دليل. "
                        "اكتب ملخصًا عربيًا من نقاط: المخاطر المحتملة، الأولويات، والفحوصات المقترحة. لا تقترح نشر كود غير مختبر.\n"
                        + json.dumps(metrics, ensure_ascii=False),
                        "مراجعة أمنية أسبوعية"
                    )
                    if ai_summary:
                        report += "\n\n🤖 ملخص المساعد الذكي:\n" + ai_summary[:2200]
                except Exception as exc:
                    log.warning("AI weekly security review failed: %s", exc)
            db.execute("INSERT OR REPLACE INTO security_review_runs(week_start,created_at,report) VALUES(?,?,?)", (week_key, now(), report[:9000]))
            db.commit()
            recipients = {int(OWNER_ID)} if OWNER_ID else set()
            recipients.update(int(r[0]) for r in db.execute(
                "SELECT user_id FROM delegated_owners WHERE user_id IN (SELECT user_id FROM staff_capabilities WHERE capability='security_review' OR capability='executive')"
            ).fetchall())
            for recipient in sorted(recipients):
                try:
                    await app.bot.send_message(chat_id=recipient, text=report[:3900])
                except Exception as exc:
                    log.warning("Weekly security review delivery failed user=%s: %s", recipient, exc)
            await asyncio.sleep(60)
        except asyncio.CancelledError:
            raise
        except Exception:
            log.exception("Weekly security review worker failed")
            await asyncio.sleep(300)


async def active_group_refresh_worker(app):
    """Continuously verify bot membership and classify groups by the configured owner's
    actual Telegram creator status. A group is owner-managed only when Telegram confirms
    OWNER_ID is its creator; all other groups using this bot remain external.
    Transient API failures never change classification or delete records.
    """
    await asyncio.sleep(30)
    while True:
        try:
            bot_user = await app.bot.get_me()
            rows = db.execute("""SELECT chat_id, title, COALESCE(is_member,1), COALESCE(is_external,1)
                FROM external_group_control
                UNION
                SELECT w.chat_id, w.title, 1, 1 FROM watched_groups w
                WHERE NOT EXISTS (SELECT 1 FROM external_group_control e WHERE e.chat_id=w.chat_id)
                ORDER BY 2 COLLATE NOCASE""").fetchall()
            for chat_id, title, was_member, was_external in rows:
                cid = int(chat_id)
                try:
                    bot_member = await app.bot.get_chat_member(chat_id=cid, user_id=bot_user.id)
                    bot_status = getattr(bot_member, "status", "unknown")
                    bot_is_member = bot_status in ("member", "administrator", "creator") or (
                        bot_status == "restricted" and getattr(bot_member, "is_member", True) is not False
                    )
                    if not bot_is_member or bot_status in ("left", "kicked"):
                        if int(was_member or 0) != 0:
                            db.execute("""UPDATE external_group_control SET enabled=0,is_member=0,
                                bot_status=?,last_checked_at=?,updated_at=? WHERE chat_id=?""",
                                (bot_status, now(), now(), cid))
                            archive_watched_group(cid, "periodic_membership_refresh_confirmed_inactive")
                            db.execute("DELETE FROM watched_groups WHERE chat_id=?", (cid,))
                            db.commit()
                            log_external_group_event(cid, 0, "bot_no_longer_member",
                                f"status={bot_status}; group removed from active lists")
                            try:
                                await notify_owners(app, (
                                    "⚠️ تنبيه مراقبة القروبات\n"
                                    f"لم يعد البوت موجودًا في القروب: {title or cid}\n"
                                    f"المعرّف: {cid}\n"
                                    "تم إخفاؤه من القوائم النشطة والنشر والتاق، مع الاحتفاظ بسجله التاريخي."
                                ), "groups")
                            except Exception as notify_exc:
                                log.warning("Could not send inactive-group notice for %s: %s", cid, notify_exc)
                        continue

                    # Confirm actual ownership using Telegram's creator status, not who added the bot.
                    owner_is_creator = False
                    if OWNER_ID:
                        try:
                            owner_member = await app.bot.get_chat_member(chat_id=cid, user_id=int(OWNER_ID))
                            owner_is_creator = getattr(owner_member, "status", "") == "creator"
                        except Exception as owner_check_exc:
                            # Failure to inspect the owner is not evidence that this is an external group.
                            log.debug("Could not verify configured owner in group %s: %s", cid, owner_check_exc)
                            owner_is_creator = None

                    current_external = int(was_external or 1)
                    if owner_is_creator is True:
                        current_external = 0
                    elif owner_is_creator is False:
                        current_external = 1

                    try:
                        chat_obj = await app.bot.get_chat(cid)
                        fresh_title = getattr(chat_obj, "title", None) or title or str(cid)
                    except Exception:
                        fresh_title = title or str(cid)

                    db.execute("""INSERT OR IGNORE INTO external_group_control
                        (chat_id,title,is_external,added_by,added_by_name,added_by_username,
                         enabled,ai_enabled,created_at,updated_at,is_member)
                        VALUES(?,?,?,0,'','',1,0,?,?,1)""",
                        (cid, fresh_title, current_external, now(), now()))
                    db.execute("""UPDATE external_group_control SET
                        title=?, is_external=?, is_member=1, bot_status=?, last_checked_at=?, updated_at=?
                        WHERE chat_id=?""",
                        (fresh_title, current_external, bot_status, now(), now(), cid))
                    if current_external == 0:
                        # Owner-owned groups belong only in the owner's lists.
                        db.execute("INSERT OR IGNORE INTO watched_groups(chat_id,title,added_at) VALUES(?,?,?)",
                                   (cid, fresh_title, now()))
                    else:
                        # External groups remain registered in the external center, never in owner lists.
                        db.execute("DELETE FROM watched_groups WHERE chat_id=?", (cid,))
                        db.execute("DELETE FROM motivation_groups WHERE chat_id=?", (cid,))
                    db.commit()
                except (Forbidden, BadRequest) as exc:
                    message = str(exc).lower()
                    if any(token in message for token in (
                        "chat not found", "bot is not a member", "not a member of the chat",
                        "not a member of the supergroup", "user not found", "was kicked", "kicked from"
                    )):
                        if int(was_member or 0) != 0:
                            db.execute("""UPDATE external_group_control SET enabled=0,is_member=0,
                                bot_status='left',last_checked_at=?,updated_at=? WHERE chat_id=?""",
                                (now(), now(), cid))
                            archive_watched_group(cid, "periodic_membership_refresh_confirmed_inactive")
                            db.execute("DELETE FROM watched_groups WHERE chat_id=?", (cid,))
                            db.execute("DELETE FROM motivation_groups WHERE chat_id=?", (cid,))
                            db.commit()
                            log_external_group_event(cid, 0, "bot_membership_lost", str(exc)[:500])
                            try:
                                await notify_owners(app, (
                                    "⚠️ تنبيه مراقبة القروبات\n"
                                    f"تأكد تعذر وصول البوت إلى القروب: {title or cid}\n"
                                    f"المعرّف: {cid}\n"
                                    "أُزيل من القوائم النشطة مع الاحتفاظ بالمعلومات التاريخية."
                                ), "groups")
                            except Exception:
                                log.exception("Failed notifying owner about unreachable group %s", cid)
                    else:
                        log.warning("Could not verify group %s; preserving its records: %s", cid, exc)
                except Exception as exc:
                    log.warning("Temporary group refresh failure; preserving %s (%s): %s", title, cid, exc)
                await asyncio.sleep(0.05)
            await asyncio.sleep(300)
        except asyncio.CancelledError:
            raise
        except Exception:
            log.exception("Active group refresh worker failed")
            await asyncio.sleep(60)


async def group_greeting_worker(app):
    """Legacy greeting sender; intentionally not started (scheduled greetings disabled)."""
    tz = ZoneInfo("Asia/Riyadh")
    messages = {
        "morning": "🌅 صباح الخير والسعادة على جميع أعضاء القروب\n\n☀️ أسعد الله صباحكم بكل خير، وكتب لكم يومًا مليئًا بالتوفيق والإنجاز والراحة.\n\n🤍 جعل الله صباحكم بداية لكل خير، ورزقكم من واسع فضله.\n\nمع تحيات بوت حماية ومساعدة القروبات 🤖",
        "evening": "🌙 مساء الخير والسرور على جميع أعضاء القروب\n\n✨ مساؤكم راحة وطمأنينة، وأوقاتكم عامرة بالخير والسعادة.\n\n🤍 نسأل الله أن يجعل مساءكم جميلًا، وأن يرزقكم راحة البال والتوفيق في كل أموركم.\n\nمع تحيات بوت حماية ومساعدة القروبات 🤖",
    }
    while True:
        try:
            current = datetime.now(tz)
            # Select the next scheduled occurrence and retain its period after sleeping.
            schedule = []
            for hour, period in ((7, "morning"), (20, "evening")):
                scheduled = current.replace(hour=hour, minute=0, second=0, microsecond=0)
                if scheduled <= current:
                    scheduled += timedelta(days=1)
                schedule.append((scheduled, period))
            scheduled_time, period = min(schedule, key=lambda item: item[0])
            await asyncio.sleep(max(1, (scheduled_time - datetime.now(tz)).total_seconds()))
            # Use the scheduled date, not a possibly delayed wall-clock date, for deduplication.
            day_key = scheduled_time.date().isoformat()
            rows = db.execute("""SELECT w.chat_id, w.title FROM watched_groups w
                JOIN external_group_control e ON e.chat_id=w.chat_id
                WHERE e.is_external=0 AND e.enabled=1 AND COALESCE(e.is_member,1)=1
                ORDER BY w.title COLLATE NOCASE""").fetchall()
            bot_user = await app.bot.get_me()
            photo_file_id = None
            try:
                photos = await app.bot.get_user_profile_photos(bot_user.id, limit=1)
                if photos.total_count and photos.photos:
                    photo_file_id = photos.photos[0][-1].file_id
            except Exception as exc:
                log.debug("Bot profile photo unavailable for greetings: %s", exc)
            for chat_id, title in rows:
                try:
                    exists = db.execute(
                        "SELECT 1 FROM group_greeting_deliveries WHERE chat_id=? AND greeting_date=? AND period=?",
                        (int(chat_id), day_key, period),
                    ).fetchone()
                    if exists:
                        continue
                    member = await app.bot.get_chat_member(chat_id=int(chat_id), user_id=bot_user.id)
                    if getattr(member, "status", "left") not in ("member", "administrator", "creator"):
                        continue
                    if photo_file_id:
                        await app.bot.send_photo(chat_id=int(chat_id), photo=photo_file_id, caption=messages[period])
                    else:
                        await app.bot.send_message(chat_id=int(chat_id), text=messages[period])
                    db.execute(
                        "INSERT OR IGNORE INTO group_greeting_deliveries(chat_id,greeting_date,period,sent_at) VALUES(?,?,?,?)",
                        (int(chat_id), day_key, period, now()),
                    )
                    db.commit()
                except asyncio.CancelledError:
                    raise
                except Exception as exc:
                    log.info("Greeting delivery skipped for group %s (%s): %s", chat_id, title, exc)
                await asyncio.sleep(0.15)
        except asyncio.CancelledError:
            raise
        except Exception:
            log.exception("Group greeting worker failed")
            await asyncio.sleep(60)


async def callback(update, context):
    """Instrument callback latency while preserving the existing dispatcher contract."""
    started = time.perf_counter()
    q = update.callback_query
    callback_data = (q.data or "") if q else ""
    try:
        return await _callback_impl(update, context)
    finally:
        elapsed_ms = (time.perf_counter() - started) * 1000
        if elapsed_ms >= 500:
            log.warning("CALLBACK_SLOW elapsed_ms=%.1f data=%s user_id=%s", elapsed_ms, callback_data[:100], q.from_user.id if q else 0)
        else:
            log.debug("CALLBACK_LATENCY elapsed_ms=%.1f data=%s", elapsed_ms, callback_data[:100])


async def ensure_global_join_approval_links_worker(app):
    """Ensure each registered group has a bot-managed request-only link when the global lock is on."""
    await asyncio.sleep(8)
    while True:
        try:
            if global_join_approval_enabled():
                groups = db.execute("""SELECT chat_id, title FROM (
                    SELECT chat_id, COALESCE(NULLIF(title,''),CAST(chat_id AS TEXT)) AS title FROM watched_groups
                    UNION
                    SELECT chat_id, COALESCE(NULLIF(title,''),CAST(chat_id AS TEXT)) AS title FROM external_group_control WHERE is_external=1 AND COALESCE(is_member,1)=1
                ) ORDER BY chat_id""").fetchall()
                created = []
                for chat_id, title in groups:
                    active = db.execute("SELECT 1 FROM managed_join_invite_links WHERE chat_id=? AND active=1 LIMIT 1", (int(chat_id),)).fetchone()
                    if active:
                        continue
                    try:
                        link = await create_managed_join_request_link(app.bot, int(chat_id))
                        created.append(f"• {title}: {link}")
                    except Exception as exc:
                        log.warning("Could not ensure join-request link for chat %s: %s", chat_id, exc)
                    await asyncio.sleep(0.15)
                if created:
                    message = "🔐 روابط طلب الانضمام (الموافقة للمالك الأساسي ونائب المالك):\n\n" + "\n".join(created)
                    recipients = ({int(OWNER_ID)} if OWNER_ID else set())
                    recipients.update(int(row[0]) for row in db.execute("SELECT user_id FROM deputy_owners").fetchall())
                    for recipient in recipients:
                        try:
                            for start in range(0, len(message), 3500):
                                await app.bot.send_message(chat_id=recipient, text=message[start:start+3500])
                        except Exception as exc:
                            log.info("Could not send join-request links to %s: %s", recipient, exc)
            await asyncio.sleep(300)
        except asyncio.CancelledError:
            raise
        except Exception:
            log.exception("Global join-approval link reconciliation failed")
            await asyncio.sleep(60)


async def friday_prayer_reminder_worker(app):
    """Send a Friday prayer reminder to active internal/external groups at 11:00 Riyadh time."""
    tz = ZoneInfo("Asia/Riyadh")
    reminder_text = (
        "🕌 تذكير صلاة الجمعة\n\n"
        "قال الله تعالى: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا نُودِيَ لِلصَّلَاةِ مِنْ يَوْمِ الْجُمُعَةِ فَاسْعَوْا إِلَىٰ ذِكْرِ اللَّهِ وَذَرُوا الْبَيْعَ﴾\n"
        "نسأل الله أن يتقبل منا ومنكم، وأن يجعل جمعتكم مباركة.\n"
        "لا تنسوا التبكير إلى الصلاة والإنصات للخطبة."
    )
    while True:
        try:
            current = datetime.now(tz)
            # Friday is weekday 4. Send at 11:00 Saudi time, without catch-up bursts.
            days_until_friday = (4 - current.weekday()) % 7
            target = current.replace(hour=11, minute=0, second=0, microsecond=0) + timedelta(days=days_until_friday)
            if target <= current:
                target += timedelta(days=7)
            await asyncio.sleep(max(1, (target - current).total_seconds()))
            friday_date = target.date().isoformat()

            group_ids = set()
            for row in owner_managed_group_rows():
                group_ids.add(int(row[0]))
            external_rows = db.execute(
                "SELECT chat_id FROM external_group_control WHERE is_external=1 AND is_member=1 AND enabled=1"
            ).fetchall()
            group_ids.update(int(row[0]) for row in external_rows)

            for chat_id in sorted(group_ids):
                already_sent = db.execute(
                    "SELECT 1 FROM friday_reminder_sent WHERE chat_id=? AND friday_date=?",
                    (chat_id, friday_date)
                ).fetchone()
                if already_sent:
                    continue
                try:
                    await app.bot.send_message(
                        chat_id=chat_id,
                        text=reminder_text,
                        disable_web_page_preview=True
                    )
                    db.execute(
                        "INSERT OR IGNORE INTO friday_reminder_sent(chat_id,friday_date,sent_at) VALUES(?,?,?)",
                        (chat_id, friday_date, now())
                    )
                    db.commit()
                    await asyncio.sleep(0.15)
                except asyncio.CancelledError:
                    raise
                except Exception as exc:
                    log.warning("Friday reminder failed for chat %s (%s)", chat_id, type(exc).__name__)
        except asyncio.CancelledError:
            raise
        except Exception:
            log.exception("Friday prayer reminder worker failed")
            await asyncio.sleep(60)


async def nabras_daily_intro_worker(app):
    """Publish Nabras' approved two-line introduction once daily at 22:00 Riyadh time
    in every registered group where AI is currently enabled; never post in channels."""
    while True:
        try:
            current = _riyadh_now()
            target = current.replace(hour=22, minute=0, second=0, microsecond=0)
            if target <= current:
                target += timedelta(days=1)
            await asyncio.sleep(max(5, (target - _riyadh_now()).total_seconds()))
            day_key = _riyadh_now().date().isoformat()
            rows = db.execute("""SELECT w.chat_id, COALESCE(NULLIF(w.title,''),CAST(w.chat_id AS TEXT))
                FROM watched_groups w
                LEFT JOIN ai_group_settings a ON a.chat_id=w.chat_id
                LEFT JOIN external_group_control e ON e.chat_id=w.chat_id
                WHERE (COALESCE(a.enabled,0)=1 OR (COALESCE(e.is_external,0)=1 AND COALESCE(e.ai_enabled,0)=1))
                  AND COALESCE(e.enabled,1)=1 AND COALESCE(e.is_member,1)=1
                ORDER BY w.title""").fetchall()
            intro = ("✨ <b>نَبْراس KFU</b>\n"
                     "أنا نَبْراس KFU مساعدك الأكاديمي الذكي المصمم لرد عن استفساراتك الدراسية بأسلوب واضح وسهل.\n"
                     "📘 اسألني عن دراستك وخدمات جامعة الملك فيصل.")
            bot_user = await app.bot.get_me()
            for chat_id, title in rows:
                cid = int(chat_id)
                if db.execute("SELECT 1 FROM nabras_intro_deliveries WHERE chat_id=? AND intro_date=?", (cid, day_key)).fetchone():
                    continue
                try:
                    chat = await app.bot.get_chat(cid)
                    if getattr(chat, "type", "") not in ("group", "supergroup"):
                        continue
                    member = await app.bot.get_chat_member(chat_id=cid, user_id=bot_user.id)
                    if getattr(member, "status", "") not in ("member", "administrator", "creator"):
                        continue
                    # Re-check enablement immediately before sending in case it was disabled after query.
                    ext = external_group_info(cid)
                    if ext and ext[0]:
                        still_enabled = bool(ext[1] and ext[2] and external_group_cap_enabled(cid, "ai"))
                    else:
                        state = db.execute("SELECT enabled FROM ai_group_settings WHERE chat_id=?", (cid,)).fetchone()
                        still_enabled = bool(state and state[0])
                    if not still_enabled:
                        continue
                    await app.bot.send_message(chat_id=cid, text=intro, parse_mode="HTML", disable_web_page_preview=True)
                    db.execute("INSERT OR IGNORE INTO nabras_intro_deliveries(chat_id,intro_date,sent_at) VALUES(?,?,?)", (cid, day_key, now()))
                    db.commit()
                except asyncio.CancelledError:
                    raise
                except Exception as exc:
                    log.info("Nabras daily introduction skipped for group %s (%s): %s", cid, title, exc)
                await asyncio.sleep(0.15)
        except asyncio.CancelledError:
            raise
        except Exception:
            log.exception("Nabras daily introduction worker failed")
            await asyncio.sleep(60)


async def publish_campaigns_worker(app):
    """Deliver due campaigns from persistent storage; safe across process restarts."""
    while True:
        try:
            due = db.execute(
                "SELECT id,creator_id,source_chat_id,source_message_id,targets_json FROM publish_campaigns "
                "WHERE status='scheduled' AND scheduled_at<>'' AND scheduled_at<=? ORDER BY scheduled_at LIMIT 10",
                (datetime.now(ZoneInfo("Asia/Riyadh")).strftime("%Y-%m-%d %H:%M"),)
            ).fetchall()
            for campaign_id, creator_id, source_chat_id, source_message_id, targets_json in due:
                # Claim before sending to prevent duplicate delivery if two worker loops overlap.
                cur = db.execute("UPDATE publish_campaigns SET status='sending' WHERE id=? AND status='scheduled'", (campaign_id,))
                db.commit()
                if not cur.rowcount:
                    continue
                try:
                    targets = json.loads(targets_json or "[]")
                except Exception:
                    targets = []
                sent = failed = 0
                errors = []
                for target in targets:
                    kind, raw_id = target.get("kind"), target.get("id")
                    try:
                        chat_id = int(raw_id)
                        if kind == "group":
                            if not await can_publish_to_live(app.bot, creator_id, chat_id):
                                raise PermissionError("انتهت صلاحية النشر في القروب")
                        elif kind == "channel":
                            if not is_owner(creator_id) or not db.execute("SELECT 1 FROM linked_channels WHERE chat_id=?", (chat_id,)).fetchone():
                                raise PermissionError("القناة لم تعد مرتبطة أو لم تعد مصرحاً بها")
                        else:
                            raise ValueError("نوع جهة نشر غير صالح")
                        await app.bot.copy_message(chat_id=chat_id, from_chat_id=int(source_chat_id), message_id=int(source_message_id))
                        sent += 1
                    except Exception as exc:
                        failed += 1
                        errors.append(f"{raw_id}: {str(exc)[:120]}")
                        log.warning("Campaign %s delivery failed for %s: %s", campaign_id, raw_id, exc)
                    await asyncio.sleep(0.08)
                result = f"نجح: {sent}\nتعذر: {failed}"
                if errors:
                    result += "\n" + "\n".join(errors[:15])
                db.execute("UPDATE publish_campaigns SET status='completed',completed_at=?,success_count=?,failed_count=?,result_text=? WHERE id=?",
                           (now(), sent, failed, result[:3000], campaign_id))
                db.commit()
                try:
                    await app.bot.send_message(int(creator_id), f"📣 اكتمل نشر الحملة #{campaign_id}\n{result}")
                except Exception:
                    log.info("Could not send campaign completion notice to creator %s", creator_id)
        except asyncio.CancelledError:
            raise
        except Exception:
            log.exception("Campaign scheduler worker failed")
        await asyncio.sleep(15)


async def post_init(app):
    """Start background workers on the running event loop and track them for clean shutdown."""
    worker_specs = [
        (active_group_refresh_worker, "active-group-refresh-worker"),
        (group_link_directory_worker, "group-link-directory-worker"),
        (assistant_reminder_worker, "assistant-reminder-worker"),
        (automatic_unmute_worker, "automatic-unmute-worker"),
        (weekly_stats_worker, "weekly-group-stats-worker"),
        (daily_member_activity_worker, "daily-member-activity-worker"),
        (bot_advertisement_worker, "bot-advertisement-worker"),
        (nabras_daily_intro_worker, "nabras-daily-intro-worker"),
        (owner_activity_audit_worker, "owner-activity-audit-worker"),
        (group_analysis_report_worker, "group-analysis-report-worker"),
        (weekly_security_review_worker, "weekly-security-review-worker"),
        (motivation_daily_worker, "motivation-daily-worker"),
        (friday_prayer_reminder_worker, "friday-prayer-reminder-worker"),
        (publish_campaigns_worker, "publish-campaigns-worker"),
        # Disabled per owner request: stop scheduled morning/evening group greetings.
        (ensure_global_join_approval_links_worker, "global-join-approval-links-worker"),
    ]
    # Application is a library object: do not assign undocumented private attributes.
    # post_init runs on the application's active event loop, so asyncio.create_task
    # is appropriate here and avoids PTB's warning for Application.create_task
    # calls made before the application enters its running state.
    tasks = []
    for worker, name in worker_specs:
        tasks.append(asyncio.create_task(worker(app), name=name))
    app.bot_data["_background_worker_tasks"] = tasks


async def post_stop(app):
    """Cancel and await long-running workers to shut down without orphaned tasks."""
    tasks = list(app.bot_data.get("_background_worker_tasks", []))
    for task in tasks:
        if not task.done():
            task.cancel()
    if tasks:
        await asyncio.gather(*tasks, return_exceptions=True)
    app.bot_data["_background_worker_tasks"] = []



async def owner_activity_audit_worker(app):
    """Notify the primary owner about logged actions by delegated owners/managers/staff."""
    # Skip historic rows at startup; only new actions generate notifications.
    try:
        latest = db.execute("SELECT COALESCE(MAX(id),0) FROM logs").fetchone()[0]
        db.execute("UPDATE owner_activity_cursor SET last_log_id=? WHERE id=1", (latest,))
        db.commit()
    except Exception:
        log.exception("تعذر تهيئة مؤشر تنبيهات نشاط الإدارة")
    while True:
        try:
            if not OWNER_ID:
                await asyncio.sleep(10)
                continue
            cursor = db.execute("SELECT last_log_id FROM owner_activity_cursor WHERE id=1").fetchone()
            last_id = int(cursor[0]) if cursor else 0
            rows = db.execute(
                "SELECT id,chat_id,user_id,action,details,created_at FROM logs WHERE id>? ORDER BY id LIMIT 100",
                (last_id,)
            ).fetchall()
            for log_id, chat_id, actor_id, action, details, created_at in rows:
                try:
                    actor_id = int(actor_id or 0)
                    is_staff_actor = bool(
                        actor_id and ((is_delegated_owner(actor_id) and not is_owner(actor_id))
                        or db.execute("SELECT 1 FROM managers WHERE user_id=?", (actor_id,)).fetchone()
                        or db.execute("SELECT 1 FROM protection_managers WHERE user_id=?", (actor_id,)).fetchone()
                        or db.execute("SELECT 1 FROM group_roles WHERE user_id=? LIMIT 1", (actor_id,)).fetchone())
                    )
                    if is_staff_actor:
                        role = role_name(actor_id)
                        name = user_display_name(actor_id)
                        group_title = "خاص/النظام" if not chat_id else str(chat_id)
                        if chat_id:
                            row = db.execute("SELECT title FROM watched_groups WHERE chat_id=?", (chat_id,)).fetchone()
                            if row and row[0]: group_title = row[0]
                        message = (
                            "🔔 تنبيه نشاط إداري\n\n"
                            f"👤 المنفّذ: {name}\n🪪 المعرّف: {actor_id}\n🏷️ الصفة: {role}\n"
                            f"⚙️ نوع الإجراء: {action or 'غير محدد'}\n📍 القروب/النطاق: {group_title}\n"
                            f"📝 التفاصيل: {(details or 'لا توجد تفاصيل')[:900]}\n🕒 الوقت: {created_at or 'غير محدد'}"
                        )
                        try:
                            await app.bot.send_message(chat_id=OWNER_ID, text=message)
                        except Exception as exc:
                            log.info("تعذر إرسال تنبيه النشاط الإداري للمالك: %s", exc)
                    db.execute("UPDATE owner_activity_cursor SET last_log_id=? WHERE id=1", (log_id,))
                    db.commit()
                except Exception:
                    log.exception("تعذر معالجة سجل النشاط الإداري %s", log_id)
                    db.execute("UPDATE owner_activity_cursor SET last_log_id=? WHERE id=1", (log_id,))
                    db.commit()
            await asyncio.sleep(5 if rows else 10)
        except asyncio.CancelledError:
            raise
        except Exception:
            log.exception("خطأ في مراقبة النشاط الإداري")
            await asyncio.sleep(10)

def main():
    if not TOKEN:
        raise RuntimeError("BOT_TOKEN غير موجود في Environment Variables.")
    app = Application.builder().token(TOKEN).post_init(post_init).post_stop(post_stop).build()

    command_handlers = {
        "stats_on": owner_group_feature_command, "stats_off": owner_group_feature_command, "joinalerts_on": owner_group_feature_command, "joinalerts_off": owner_group_feature_command, "leavealerts_on": owner_group_feature_command, "leavealerts_off": owner_group_feature_command, "analysis_on": owner_group_feature_command, "analysis_off": owner_group_feature_command, "joinapproval_on": owner_group_feature_command, "joinapproval_off": owner_group_feature_command, "lockall": lock_all_messages_command, "unlockall": lock_all_messages_command,
        "start": start, "help": help_cmd, "panel": panel, "motivation": motivation_cmd, "ai": ai_cmd, "aigroups": aigroups_cmd, "calendar": calendar_cmd, "adhkar": adhkar_cmd, "staffdone": staffdone_cmd, "report": report_cmd, "groupstats": group_stats_cmd,
        "note": assistant_note_cmd, "notes": assistant_notes_cmd, "usage": assistant_usage_cmd, "clear_ai": assistant_clear_ai_cmd,
        "remind": assistant_remind_cmd, "reminders": assistant_reminders_cmd, "delreminder": assistant_delreminder_cmd, "assistantstats": assistant_stats_cmd,
        "task": assistant_task_cmd, "tasks": assistant_tasks_cmd, "donetask": assistant_done_task_cmd, "deltask": assistant_delete_task_cmd,
        "expense": assistant_expense_cmd, "expenses": assistant_expenses_cmd, "summarize": assistant_summarize_cmd, "quiz": assistant_quiz_cmd,
        "addowner": addowner, "delowner": delowner, "owners": owners_cmd,
        "adddeputy": adddeputy, "deldeputy": deldeputy,
        "grantpublish": grantpublish, "revokepublish": revokepublish,
        "grantcap": grantcap, "revokecap": revokecap, "groupreport": groupreport_cmd, "aistatus": aistatus_cmd,
        "addchannel": addchannel_cmd, "delchannel": delchannel_cmd, "channels": channels_cmd,
        "publishchannels": publish_channels_cmd, "ask": ask_cmd,
        "addprotect": addprotect, "delprotect": delprotect, "permissions": permissions_cmd,
        "addmanager": addmanager, "delmanager": delmanager, "managers": managers,
        "id": id_cmd, "idgroup": idgroup, "monitor": monitor_cmd, "badges": badges_cmd, "badge_remove": badge_remove_cmd,
        "memberpoints": member_points_cmd, "membertop": member_top_cmd, "givepoints": give_member_points_cmd, "setmembertitle": set_member_title_cmd,
        "dailyactivity": daily_activity_settings_cmd,
        "ban": ban, "unban": unban, "kick": kick, "mute": mute, "unmute": unmute, "warn": warn_cmd,
        "muted": muted_cmd, "unmuteall": unmuteall_cmd, "del": del_cmd, "pin": pin,
        "alerts": alerts, "logs": logs_cmd, "settings": settings_cmd, "locks": locks,
        "archive": archive_cmd, "archive_on": archive_on, "archive_off": archive_off,
        "autoreplies": auto_replies_list, "autoreplies_on": auto_replies_on,
        "autoreplies_off": auto_replies_off, "addreply": add_auto_reply, "delreply": delete_auto_reply
    }
    for name, fn in command_handlers.items():
        app.add_handler(CommandHandler(name, fn))
    app.add_handler(CommandHandler("cancel", cancel_owner_autoreply), group=-2)
    app.add_handler(MessageHandler(filters.ChatType.PRIVATE & filters.TEXT & ~filters.COMMAND, lock_all_groups_text), group=-6)
    app.add_handler(MessageHandler(filters.ChatType.PRIVATE & ~filters.COMMAND, process_private_workflows), group=-5)
    app.add_handler(MessageHandler(filters.ChatType.PRIVATE & filters.TEXT & ~filters.COMMAND, assistant_private_text), group=-4)
    app.add_handler(MessageHandler(filters.ChatType.GROUPS & filters.TEXT & ~filters.COMMAND, ai_auto_group_reply), group=-3)
    app.add_handler(MessageHandler(filters.ChatType.PRIVATE & filters.Document.ALL, assistant_private_document), group=-4)

    for cmd in LOCK_MAP:
        app.add_handler(CommandHandler(cmd, set_lock))

    app.add_handler(CallbackQueryHandler(callback))
    app.add_handler(MessageHandler(filters.ChatType.PRIVATE & ~filters.COMMAND, owner_autoreply_text_handler), group=-2)
    app.add_handler(MessageHandler(filters.ChatType.PRIVATE & ~filters.COMMAND, broadcast_draft_message), group=-1)
    app.add_handler(MessageHandler(filters.UpdateType.CHANNEL_POST, channel_post_listener), group=-1)
    # Profile-name changes are already tracked by message_filter via member_activity.
    # Registering a second all-messages handler duplicated DB reads/writes and notifications.
    app.add_handler(ChatMemberHandler(my_chat_member_handler, ChatMemberHandler.MY_CHAT_MEMBER), group=0)
    app.add_handler(ChatMemberHandler(chat_member_handler, ChatMemberHandler.CHAT_MEMBER), group=0)
    app.add_handler(ChatJoinRequestHandler(chat_join_request_handler), group=0)
    # Enforce the add-service-message setting independently from member tracking/welcome.
    app.add_handler(MessageHandler(filters.StatusUpdate.NEW_CHAT_MEMBERS, service_add_handler), group=0)
    app.add_handler(MessageHandler(filters.StatusUpdate.NEW_CHAT_MEMBERS, new_members), group=1)
    app.add_handler(MessageHandler(filters.ALL & ~filters.COMMAND, ArabicTextCommand), group=2)
    app.add_handler(MessageHandler(filters.ALL & ~filters.COMMAND, message_filter), group=3)
    app.add_handler(MessageHandler(filters.UpdateType.EDITED_MESSAGE, edited_filter), group=4)
    async def error_handler(update, context):
        # Avoid noisy failures for idempotent UI edits and explain polling conflicts clearly.
        error = context.error
        error_text = str(error or "")
        if isinstance(error, BadRequest) and "message is not modified" in error_text.lower():
            log.debug("Ignored Telegram no-op edit: %s", error_text)
            return
        if "terminated by other getUpdates request" in error_text or "Conflict: terminated by other getUpdates request" in error_text:
            log.error("Telegram polling conflict: another instance is polling this bot token. Stop duplicate Render/local instances; only one polling process may run.")
            return
        if isinstance(error, (httpx.TimeoutException, httpx.NetworkError)) or "Bad Gateway" in error_text or "Timed out" in error_text:
            # Telegram/network transient failures should be visible without treating a
            # single failed request as a fatal application error. PTB's polling loop retries.
            log.warning("Temporary Telegram/network error; polling should retry automatically: %s", error)
            return
        log.error("Update error: %s", error, exc_info=error)

    app.add_error_handler(error_handler)

    threading.Thread(target=start_health_server, daemon=True).start()
    log.info("Bot started")
    app.run_polling(allowed_updates=Update.ALL_TYPES)

if __name__ == "__main__":
    main()
